local Image = CS.UnityEngine.UI.Image




--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool

local DreamSpaceUtils = CS.DreamSpace.DreamSpaceUtils


local ElectricalApplianceBase = CS.ElectricalSystem.ElectricalApplianceBase
local OnOff = CS.Game.OnOff
local LuaParameters = CS.Engine.Modules.LuaParameters


-- ========================================================


function Gear_1_InLvl1:__init()
    self.controller = nil
end


function Gear_1_InLvl1:__delete()
    self.co_1 = nil

    if not isNull(self.co_2) then 
        cs_coroutine.stop(self.co_2)
        self.co_2 = nil
    end
end



function Gear_1_InLvl1:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end

function Gear_1_InLvl1:Start()
    KTool.SetActive(self.controller.gameObject, true)

    assert( self.door and self.questBH and self.params )
    self.quest = DreamSpaceLuaUtils.GetLuaScr(self.questBH.gameObject, "Game.DreamSpace.Level1.Quest.QuestLvl1" )
    self.taskRange = QuestUtils.ReadTaskRangeFromLuaParameters( self.params )
    assert( self.quest and self.taskRange )
    assert(self.taskRange:IsSetedInInspector())


    self.door:WhenElectrifiedStateChanged( '+', function( state_ )
        self:WhenDoorElectrifiedStateChanged( state_ )
    end )

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(self.DelayInit, self)
end



function Gear_1_InLvl1:DelayInit() 

    while (isNull(self.quest.core)) or (self.quest.core.isInit == false) do
        coroutine.yield(Yielders.EndOfFrame)
    end

    self.taskRange:Init(self.quest.core)
    self.quest:RegistSwitchTaskFunc(self.taskRange, Bind(self, self.SwitchTask) ) -- todo: 会出问题...

end

    

function Gear_1_InLvl1:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    DreamSpaceLuaUtils.StopCoroutine( self.co_2 )
    self.co_1 = nil 
    self.co_2 = nil 
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --






---@return void
---@param state_ ElectricalSystem.ElectrifiedState
function Gear_1_InLvl1:WhenDoorElectrifiedStateChanged(state_)
    if state_.isOn == OnOff.On then
        assert(self.taskRange.isInit)
        DreamSpaceLuaUtils.StopCoroutine( self.co_2 )
        self.co_2 = cs_coroutine.start( function()
            self.quest:ToNextTask(self.taskRange)
            
        end)
    end
end




---@return System.Collections.IEnumerator
---@param taskSwitchData_ TaskSwitchData
function Gear_1_InLvl1:SwitchTask(taskSwitchData_)
    -- ------ 切换 ui texts 显示:
    local newTask = self.quest.core:GetTask(taskSwitchData_.newTaskIdx)
    assert( newTask )

    -- 旧的 打勾:
    cs_coroutine.yield_return( self.quest.ui_taskPanel:ShowTick() )
    

    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5) )

    --移动至下一个浮标指引位置
    cs_coroutine.yield_return( self.quest.floatingMarkerManager:MoveToNextAnchor() )

    -- 隐藏旧的 tsk
    cs_coroutine.yield_return( self.quest.ui_taskPanel:HideOldTask() )

    cs_coroutine.yield_return( Yielders.GetWaitForSeconds(2.5) ) --等待到相机归位至追背视角

    --居中显示任务信息
    cs_coroutine.yield_return( self.quest.ui_promptDialog:PlayEntry(newTask.taskDescription) )

    cs_coroutine.yield_return( Yielders.GetWaitForSeconds(2.5) )

    cs_coroutine.yield_return( self.quest.ui_promptDialog:PlayOut() )

    cs_coroutine.yield_return( Yielders.GetWaitForSeconds(0.5) )

    -- 显示新的 task:
    cs_coroutine.yield_return( self.quest.ui_taskPanel:ShowNewTask( newTask.taskDescription ) )

    
end



return Gear_1_InLvl1
